  ('N4-02', 'listening', 2, 32, 'choice', '', '[{"key": "A", "text": "有点儿后悔"}, {"key": "B", "text": "很满意"}, {"key": "C", "text": "觉得可惜"}, {"key": "D", "text": "无所谓"}]'::jsonb, 'B', 'auto', 1, '/mock-tests/n4-02/listening-v2.mp3', null, false, array['sk.listening.passage']::text[], '«这是我做过的最正确的决定» — хамгийн зөв шийдвэр гэж үзэж байгаа нь сэтгэл хангалуун. Харамсаж буй нь найзууд нь.', 952.8, 1026.7, '男：我大学学的是法律，毕业后在一家律师事务所工作了五年。那份工作收入不错，可是我每天都很忙，一点儿自己的时间都没有。三年前，我决定回到家乡，开了一家小书店。现在我的收入只有以前的一半，但是我每天可以看书、和客人聊天儿，晚上还能陪孩子。朋友们觉得很可惜，我却觉得这是我做过的最正确的决定。
问：说话人对现在的生活是什么态度？', '{"transcript": [{"zh": "男：我大学学的是法律，毕业后在一家律师事务所工作了五年。那份工作收入不错，可是我每天都很忙，一点儿自己的时间都没有。三年前，我决定回到家乡，开了一家小书店。现在我的收入只有以前的一半，但是我每天可以看书、和客人聊天儿，晚上还能陪孩子。朋友们觉得很可惜，我却觉得这是我做过的最正确的决定。"}, {"zh": "问：说话人对现在的生活是什么态度？"}], "why": "«这是我做过的最正确的决定» — хамгийн зөв шийдвэр гэж үзэж байгаа нь сэтгэл хангалуун. Харамсаж буй нь найзууд нь."}'::jsonb),
  ('N4-02', 'reading', 1, 33, 'fill_word', '飞机（     ）起飞了，一分钟也没有晚。', '[{"key": "A", "text": "稍微"}, {"key": "B", "text": "负责"}, {"key": "C", "text": "准时"}, {"key": "D", "text": "减少"}, {"key": "E", "text": "仍然"}]'::jsonb, 'C', 'auto', 1, null, null, false, array['sk.reading.cloze','voc.hsk4']::text[], '«准时» — яг цагтаа. «一分钟也没有晚» гэдэгтэй утга таарна.', null, null, null, null),
  ('N4-02', 'reading', 1, 34, 'fill_word', '这件事由小王（     ），有问题你可以直接问他。', '[{"key": "A", "text": "稍微"}, {"key": "B", "text": "负责"}, {"key": "C", "text": "准时"}, {"key": "D", "text": "减少"}, {"key": "E", "text": "仍然"}]'::jsonb, 'B', 'auto', 1, null, null, false, array['sk.reading.cloze','voc.hsk4']::text[], '«由…负责» — …хариуцна. Тогтсон бүтэц.', null, null, null, null),
  ('N4-02', 'reading', 1, 35, 'fill_word', '已经夜里十二点了，他（     ）在办公室里工作。', '[{"key": "A", "text": "稍微"}, {"key": "B", "text": "负责"}, {"key": "C", "text": "准时"}, {"key": "D", "text": "减少"}, {"key": "E", "text": "仍然"}]'::jsonb, 'E', 'auto', 1, null, null, false, array['sk.reading.cloze','voc.hsk4']::text[], '«仍然» — одоо хүртэл, хэвээр. Шөнийн 12 болсон ч ажилласаар байна.', null, null, null, null),
  ('N4-02', 'reading', 1, 36, 'fill_word', '为了（     ）污染，越来越多的人选择坐地铁上班。', '[{"key": "A", "text": "稍微"}, {"key": "B", "text": "负责"}, {"key": "C", "text": "准时"}, {"key": "D", "text": "减少"}, {"key": "E", "text": "仍然"}]'::jsonb, 'D', 'auto', 1, null, null, false, array['sk.reading.cloze','voc.hsk4']::text[], '«减少污染» — бохирдлыг багасгах.', null, null, null, null),
  ('N4-02', 'reading', 1, 37, 'fill_word', '汤有点儿淡，再（     ）放一点儿盐就更好了。', '[{"key": "A", "text": "稍微"}, {"key": "B", "text": "负责"}, {"key": "C", "text": "准时"}, {"key": "D", "text": "减少"}, {"key": "E", "text": "仍然"}]'::jsonb, 'A', 'auto', 1, null, null, false, array['sk.reading.cloze','voc.hsk4']::text[], '«稍微 + үйл үг + 一点儿» — жаахан, бага зэрэг.', null, null, null, null),
